From ecbebe4fedec4815651e70b716b78ea1aee34313 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:12:19 +0100
Subject: [PATCH] folder: don't open a second delete confirmation dialog

Deleting or trashing with confirmation opened a new dialog each time,
because it can't be modal to the desktop. Now further delete, trash or
empty trash requests are ignored while a confirmation is still open.

BUG: 387988
---
 .../desktop/plugins/folder/foldermodel.cpp    | 21 +++++++++++++++----
 .../desktop/plugins/folder/foldermodel.h      |  3 +++
 2 files changed, 20 insertions(+), 4 deletions(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..882334f297 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -2391,7 +2391,7 @@ void FolderModel::setShowHiddenFiles(bool enable)

 void FolderModel::moveSelectedToTrash()
 {
-    if (!m_selectionModel->hasSelection()) {
+    if (!m_selectionModel->hasSelection() || m_deleteConfirmationJob) {
         return;
     }

@@ -2412,12 +2412,12 @@ void FolderModel::moveSelectedToTrash()
     using Iface = KIO::AskUserActionInterface;
     auto *job = new KIO::DeleteOrTrashJob(selectedUrls(), Iface::Trash, Iface::DefaultConfirmation, this);
     job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
-    job->start();
+    startDeleteOrTrashJob(job);
 }

 void FolderModel::deleteSelected()
 {
-    if (!m_selectionModel->hasSelection()) {
+    if (!m_selectionModel->hasSelection() || m_deleteConfirmationJob) {
         return;
     }

@@ -2429,6 +2429,15 @@ void FolderModel::deleteSelected()

     using Iface = KIO::AskUserActionInterface;
     auto *job = new KIO::DeleteOrTrashJob(selectedUrls(), Iface::Delete, Iface::DefaultConfirmation, this);
+    startDeleteOrTrashJob(job);
+}
+
+void FolderModel::startDeleteOrTrashJob(KIO::DeleteOrTrashJob *job)
+{
+    m_deleteConfirmationJob = job;
+    connect(job, &KIO::DeleteOrTrashJob::started, this, [this] {
+        m_deleteConfirmationJob.clear();
+    });
     job->start();
 }

@@ -2444,9 +2453,13 @@ void FolderModel::undo()

 void FolderModel::emptyTrashBin()
 {
+    if (m_deleteConfirmationJob) {
+        return;
+    }
+
     using Iface = KIO::AskUserActionInterface;
     auto *job = new KIO::DeleteOrTrashJob({}, Iface::EmptyTrash, Iface::DefaultConfirmation, this);
-    job->start();
+    startDeleteOrTrashJob(job);
 }

 void FolderModel::restoreSelectedFromTrash()
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..df8fc9dc06 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -44,6 +44,7 @@ class KJob;

 namespace KIO
 {
+class DeleteOrTrashJob;
 class StatJob;
 }

@@ -368,6 +369,7 @@ private:
     static bool isTrashEmpty();
     static bool isDeleteCommandShown();
     QList<QUrl> selectedUrls() const;
+    void startDeleteOrTrashJob(KIO::DeleteOrTrashJob *job);
     KDirModel *m_dirModel;
     KDirWatch *m_dirWatch;
     QString m_url;
@@ -385,6 +387,7 @@ private:
     QTimer *m_dropTargetPositionsCleanup;
     QPointer<KFilePreviewGenerator> m_previewGenerator;
     QPointer<KAbstractViewAdapter> m_viewAdapter;
+    QPointer<KJob> m_deleteConfirmationJob;
     KActionCollection m_actionCollection;
     KNewFileMenu *m_newMenu;
     KFileItemActions *m_fileItemActions;
